<dialog id="customer-signout-dialog" class="customer-signout-dialog" aria-labelledby="signout-title" aria-describedby="signout-description">
    <button class="signout-dialog-close" type="button" data-cancel-signout aria-label="Close sign-out confirmation"><i class="fa-solid fa-xmark" aria-hidden="true"></i></button>
    <span class="signout-dialog-icon"><i class="fa-solid fa-arrow-right-from-bracket" aria-hidden="true"></i></span>
    <p class="signout-dialog-kicker">UNTIL THE NEXT LITTLE LOVELY</p>
    <h2 id="signout-title">Sign out for now?</h2>
    <p id="signout-description">You can sign back in anytime to view your orders and manage your account.</p>
    <div class="signout-dialog-actions"><button type="button" data-cancel-signout autofocus>Stay signed in</button><button type="button" id="confirm-customer-signout">Sign out <i class="fa-solid fa-arrow-right" aria-hidden="true"></i></button></div>
</dialog>
